class Animal {
public:
    virtual ~Animal() = default;  // Requires at least one virtual function
    virtual void speak() const = 0;
};

class Dog : public Animal {
public:
    void speak() const override { cout << "Woof!\n"; }
    void fetch() const { cout << "Fetching...\n"; }
};

class Cat : public Animal {
public:
    void speak() const override { cout << "Meow!\n"; }
    void purr() const { cout << "Purring...\n"; }
};

void interact(const Animal& animal) {
    if (const Dog* dog = dynamic_cast<const Dog*>(&animal)) {
        dog->fetch();  // Safe: we confirmed it's a Dog
    } else if (const Cat* cat = dynamic_cast<const Cat*>(&animal)) {
        cat->purr();   // Safe: we confirmed it's a Cat
    }
}

